// ============================================================================
// CS 29 — linq-deep-dive — ORIGINAL (compiles, runs... and does the work 5x)
// Run from repo root:  dotnet run csharp/29-linq-deep-dive/original.cs
// ============================================================================
// A nightly report over a sensor feed. Reading a sensor is SLOW (20ms each),
// so the feed prints a line every time it produces a value. There are only 6
// readings — watch how many times the sensor gets asked for them.
//
// Nothing here is "wrong" in the compiler's eyes. The bug is that a LINQ query
// is a RECIPE, not a RESULT: every stat below re-runs the whole recipe.

using System.Diagnostics;

// This call runs NO code. It builds an iterator and hands it back — the first
// reading is not produced until somebody enumerates. (Count the printed lines:
// zero so far.)
IEnumerable<Reading> readings = LoadReadings();
Console.WriteLine("query built — sensor readings produced so far: " + Meter.Produced);
Console.WriteLine();

var sw = Stopwatch.StartNew();

Console.WriteLine("=== the nightly sensor report ===");
Console.WriteLine($"readings : {readings.Count()}");                        // pass 1
Console.WriteLine($"average  : {readings.Average(r => r.Celsius):0.0}C");   // pass 2
Console.WriteLine($"coldest  : {readings.Min(r => r.Celsius):0.0}C");       // pass 3
Console.WriteLine($"hottest  : {readings.Max(r => r.Celsius):0.0}C");       // pass 4
Console.WriteLine($"alerts   : {readings.Count(r => r.Celsius > 30m)}");    // pass 5

sw.Stop();
Console.WriteLine();
Console.WriteLine($"6 readings exist. The sensor produced {Meter.Produced} of them.");
Console.WriteLine($"Five stats = five full enumerations = {sw.ElapsedMilliseconds}ms of sleeping.");
Console.WriteLine("Every `readings.Something()` re-ran the whole feed from scratch.");

// ---------------------------------------------------------------------------
// Surprise #2: the query does not remember the variable's VALUE, it remembers
// the VARIABLE. Deferred execution reads it whenever the query finally runs.
// ---------------------------------------------------------------------------
Console.WriteLine();
Console.WriteLine("=== the alert threshold that moved ===");

decimal alertAbove = 30m;
var alerts = readings.Where(r => r.Celsius > alertAbove);   // still nothing runs
Console.WriteLine($"alert query built with alertAbove = {alertAbove}");

// ...forty lines of unrelated code later, someone reuses the same variable for
// a different calculation. It looks harmless. It is not.
alertAbove = 100m;

Console.WriteLine($"alerts over {30m}C: {alerts.Count()}");   // says 0. There are 2.
Console.WriteLine("Expected 2 (31.2C and 34.8C). Got 0 — because `alertAbove` was");
Console.WriteLine("100 by the time the query actually ran. The lambda captured the");
Console.WriteLine("variable, not the number, and nothing about the code LOOKS wrong.");

Console.WriteLine();
Console.WriteLine($"total sensor readings produced for a 6-reading report: {Meter.Produced}");

// The expensive source. Each `yield return` hands one item to whoever is
// enumerating and then FREEZES here until the next item is requested.
IEnumerable<Reading> LoadReadings()
{
    (string Sensor, decimal Celsius)[] raw =
    {
        ("north", 18.5m), ("north", 31.2m), ("south", 27.0m),
        ("south", 34.8m), ("roof", 12.4m), ("roof", 22.1m),
    };

    foreach (var (sensor, celsius) in raw)
    {
        Meter.Produced++;
        Console.WriteLine($"   ...reading the {sensor} sensor (#{Meter.Produced})");
        Thread.Sleep(20);                 // a real sensor / HTTP call / DB row
        yield return new Reading(sensor, celsius);
    }
}

record Reading(string Sensor, decimal Celsius);

// A global counter, so the demo can prove how much work really happened.
static class Meter
{
    public static int Produced;
}

# 🏋️ Practice: LINQ Deep Dive (Deferred Execution)

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Two more numbers for free (warm-up)

Add `Spread` (hottest minus coldest) and `AlertRate` (alerts as a fraction of readings) to `ReadingStats`. Neither may add a constructor parameter, a LINQ call, or an enumeration: both are already implied by numbers the fold collects.

Practices: derived properties vs "just add another LINQ call", and the habit of asking "does this need a pass?" before writing one.

Hint: they are computed properties like `Average`, with the same `Count == 0` guard. `AlertRate` needs one cast — integer division would report every rate as 0.

Check it offline: add to `Tests.cs` — all should pass:
```csharp
var spread = Statistics.Summarize([new Reading("a", 10m), new Reading("b", 36m), new Reading("c", 20m)], 30m);
Check.Equal(26m, spread.Spread, "spread is Max - Min");
Check.Equal(1m / 3m, spread.AlertRate, "one alert in three readings");
var none = Statistics.Summarize([], 30m);
Check.Equal(0m, none.Spread, "an empty report has no spread instead of a crash");
Check.Equal(0m, none.AlertRate, "...and no rate, instead of a divide by zero");
```

### ⭐⭐ 2. Fold one more fact in (core)

The report should name the hottest sensor, not just the temperature. Add `HottestSensor` to `ReadingStats` — a real constructor parameter this time — and set it in `Add`. Still one pass. You will also have to update `SummarizeTheSlowWay`, which builds the record positionally; that is the point of keeping it around.

Practices: growing an accumulator instead of adding a pass, and feeling why two implementations of the same thing must be kept honest by a test.

Hint: inside `Add`, the new sensor wins exactly when the new reading also becomes the new `Max` — including the very first reading, when `Count == 0`. In `SummarizeTheSlowWay`, `readings.MaxBy(r => r.Celsius).Sensor` does it in one more (sixth!) pass.

Check it offline: add to `Tests.cs` — all should pass:
```csharp
var hot = Statistics.Summarize([new Reading("north", 10m), new Reading("roof", 36m), new Reading("south", 20m)], 30m);
Check.Equal("roof", hot.HottestSensor, "the fold remembered which sensor was hottest");
Check.Equal("", Statistics.Summarize([], 30m).HottestSensor, "an empty report names nobody");
Check.Equal("only", Statistics.Summarize([new Reading("only", -5m)], 30m).HottestSensor, "a single reading is the hottest one");
var counted = new CountingSource<Reading>(new Reading("a", 1m), new Reading("b", 2m));
Statistics.Summarize(counted, 30m);
Check.Equal(1, counted.Passes, "and it still costs exactly one pass");
```

### ⭐⭐ 3. A sequence that refuses a second walk (core)

Write `SingleUse<T> : IEnumerable<T>` in `Sources.cs` — it wraps a sequence and throws `InvalidOperationException` the *second* time anybody starts enumerating it. Then use it to prove, as a test, that `Summarize` is safe to point at a network stream and `SummarizeTheSlowWay` is not.

Practices: modelling a real constraint (streams, readers) as a type you can test against, and the difference between "works on my `List`" and "works on the source I will actually get".

Hint: unlike `CountingSource`, `GetEnumerator` here must **not** be an iterator method — an iterator's body would not run until the first `MoveNext()`, and the guard has to fire when enumeration *starts*. Set a `bool used` flag and `return source.GetEnumerator();`.

Check it offline: add to `Tests.cs` — all should pass:
```csharp
Reading[] sample = [new("a", 10m), new("b", 20m), new("c", 36m)];
var oneShot = new SingleUse<Reading>(sample);
Check.Equal(3, Statistics.Summarize(oneShot, 30m).Count, "Summarize needs exactly one walk, so a stream is fine");
Check.Throws<InvalidOperationException>(
    () => Statistics.SummarizeTheSlowWay(new SingleUse<Reading>(sample), 30m),
    "the five-pass version dies on the second walk — as it would on a real stream");
Check.Throws<InvalidOperationException>(
    () => { var s = new SingleUse<Reading>(sample); s.Count(); s.Count(); },
    "two walks is two walks, however innocent they look");
```

### ⭐⭐⭐ 4. The number you cannot stream (challenge)

Add `Statistics.Median(IReadOnlyList<Reading> readings)`. A median needs every value sorted, so it cannot be folded — and the signature should say so: take `IReadOnlyList<Reading>`, not `IEnumerable<Reading>`, so the compiler makes the caller materialize first.

Practices: choosing a parameter type as documentation, and recognising the operations (median, percentile, shuffle, "last N") that genuinely require the whole set.

Hint: `readings.Select(r => r.Celsius).OrderBy(c => c).ToList()`, then pick the middle — or average the two middles when the count is even. Guard the empty case.

Check it offline: add to `Tests.cs` — all should pass:
```csharp
Check.Equal(20m, Statistics.Median([new("a", 10m), new("b", 36m), new("c", 20m)]), "odd count takes the middle value");
Check.Equal(15m, Statistics.Median([new("a", 10m), new("b", 20m)]), "even count averages the two middles");
Check.Equal(0m, Statistics.Median([]), "an empty report has no median");
Check.Equal(10m, Statistics.Median([new("a", 10m)]), "one reading is its own median");
// And the design point, in a comment you can verify by trying it:
// Statistics.Median(someSensorFeed.Stream())  ->  does not compile.
```

### ⭐⭐⭐ 5. Lazy AND replayable (challenge)

`ToList()` fixes multiple enumeration by giving up laziness: it produces everything, immediately. Write `Memoized<T> : IEnumerable<T>` that does both — it pulls from the source only as far as the consumer asks, caches every item it has seen, and serves later walks from the cache without touching the source again.

Practices: an iterator that reads its own state (`yield return` inside a loop that may be re-entered), and the realisation that "lazy" and "replayable" are separate properties you can have at once.

Hint: hold the source's `IEnumerator<T>`, a `List<T> cache` and a `bool exhausted`. In `GetEnumerator`, walk an index `i`: if `i` is inside the cache, yield the cached item; if not, pull one more from the source (caching it) or finish. Not thread-safe, and that is a fair trade for twelve lines.

Check it offline: add to `Tests.cs` — all should pass:
```csharp
var feed = new SensorFeed();                       // no delay, but it counts
var memo = new Memoized<Reading>(feed.Stream());
var slow = Statistics.SummarizeTheSlowWay(memo, 30m);   // five walks!
Check.Equal(6, slow.Count, "the numbers are right");
Check.Equal(6, feed.Produced, "...and the sensor was read six times, not thirty");

var peek = new SensorFeed();
var lazyMemo = new Memoized<Reading>(peek.Stream());
_ = lazyMemo.First();
Check.Equal(1, peek.Produced, "still lazy: one item asked for, one item produced");
Check.Equal(6, lazyMemo.Count(), "a later full walk fills the rest of the cache");
Check.Equal(6, peek.Produced, "and a third walk costs the sensor nothing");
```

## Solutions

### 1. Two more numbers for free

```csharp
// In ReadingStats, next to Average:
public decimal Spread => Count == 0 ? 0m : Max - Min;
public decimal AlertRate => Count == 0 ? 0m : (decimal)AlertCount / Count;
```

WHY: both are functions of data the fold already has, so they cost nothing and cannot drift out of sync with the numbers they are derived from — the same reason `Average` is a property instead of a sixth `Sum`-like field. The cast in `AlertRate` matters: `AlertCount / Count` is integer division, which would report 1-in-3 as `0` and pass a sloppy test that only checked "less than one". And note what you did *not* do: reach for `readings.Count(r => r.Celsius > threshold) / (decimal)readings.Count()`, which is two more passes over the source for a number you already own.

### 2. Fold one more fact in

```csharp
public sealed record ReadingStats(
    int Count, decimal Min, decimal Max, decimal Sum, int AlertCount, string HottestSensor)
{
    public static readonly ReadingStats Empty = new(0, 0m, 0m, 0m, 0, "");

    public ReadingStats Add(Reading r, decimal alertAbove) => new(
        Count: Count + 1,
        Min: Count == 0 ? r.Celsius : Math.Min(Min, r.Celsius),
        Max: Count == 0 ? r.Celsius : Math.Max(Max, r.Celsius),
        Sum: Sum + r.Celsius,
        AlertCount: AlertCount + (r.Celsius > alertAbove ? 1 : 0),
        HottestSensor: Count == 0 || r.Celsius > Max ? r.Sensor : HottestSensor);
}

// SummarizeTheSlowWay grows a SIXTH pass to keep up:
HottestSensor: readings.MaxBy(r => r.Celsius).Sensor);
```

WHY: the accumulator is where "one more thing to know about the data" belongs — adding a field costs no extra traversal, while adding a LINQ call costs a whole one. The `Count == 0 ||` half of the condition is the classic seed bug: without it the first reading loses to `Max`'s meaningless `0m` and a report of sub-zero temperatures names nobody. Notice the cost asymmetry the exercise exposes: the fold absorbed the new fact for free, the multi-pass version needed a sixth walk — and the test that compares the two is what stops them quietly disagreeing.

### 3. A sequence that refuses a second walk

```csharp
/// Streams, sockets and DB readers can only be walked once. This is that
/// constraint, as a type you can point tests at.
public sealed class SingleUse<T> : IEnumerable<T>
{
    private readonly IEnumerable<T> source;
    private bool used;

    public SingleUse(IEnumerable<T> source) => this.source = source;

    // NOT an iterator method: no `yield` anywhere, so this body runs the moment
    // somebody calls GetEnumerator() — which is exactly when the guard must fire.
    public IEnumerator<T> GetEnumerator()
    {
        if (used) throw new InvalidOperationException("this sequence has already been consumed");
        used = true;
        return source.GetEnumerator();
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
}
```

WHY: the iterator-vs-plain-method distinction is the subtle half. Written with `yield return`, the guard would not run until the first `MoveNext()`, so `foreach (var x in s) break;` twice could slip past it — and worse, `Count()` on an empty source would behave differently from `Count()` on a full one. The test it enables is the valuable part: "walks its input once" stops being a comment about `Summarize` and becomes a property that a future refactor cannot quietly break. Real `IEnumerable`s that behave this way are everywhere (`File.ReadLines` mid-iteration, `SqlDataReader`, `Channel.ReadAllAsync`), and none of them are marked by the type system.

### 4. The number you cannot stream

```csharp
/// IReadOnlyList, not IEnumerable, ON PURPOSE: a median needs every value
/// sorted, so the caller must materialize first — and now the compiler says so.
public static decimal Median(IReadOnlyList<Reading> readings)
{
    if (readings.Count == 0) return 0m;
    var sorted = readings.Select(r => r.Celsius).OrderBy(c => c).ToList();
    int mid = sorted.Count / 2;
    return sorted.Count % 2 == 1
        ? sorted[mid]
        : (sorted[mid - 1] + sorted[mid]) / 2m;
}
```

WHY: this is the exception that proves the project's rule. Count, sum, min, max and alerts can all be folded; median, percentiles, "the last 10", shuffling and sorting cannot — they need the whole set. The design move is to make the requirement visible in the *signature* rather than hiding it behind an `IEnumerable<T>` that will be walked twice (once for `Count()`, once for `OrderBy`) and will misbehave on a stream. A parameter type is documentation the compiler enforces: `Median(feed.Stream())` does not compile, and the caller is pushed to the `ToList()` they needed anyway.

### 5. Lazy AND replayable

```csharp
/// Lazy like a query, replayable like a list: items are pulled from the source
/// only as far as anyone has asked, and remembered for every later walk.
public sealed class Memoized<T> : IEnumerable<T>
{
    private readonly IEnumerator<T> source;
    private readonly List<T> cache = new();
    private bool exhausted;

    public Memoized(IEnumerable<T> source) => this.source = source.GetEnumerator();

    public IEnumerator<T> GetEnumerator()
    {
        int i = 0;
        while (true)
        {
            if (i == cache.Count)                       // past what we have seen
            {
                if (exhausted) yield break;             // ...and there is no more
                if (!source.MoveNext())
                {
                    exhausted = true;
                    source.Dispose();
                    yield break;
                }
                cache.Add(source.Current);              // one more item, remembered
            }
            yield return cache[i];
            i++;
        }
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
}
```

WHY: `ToList()` and laziness look like opposites — one produces everything now, the other produces nothing until asked — and this class is the proof that they are not. Each walk reads from the cache while it can and extends it by exactly one item when it must, so five passes over a six-item feed cost six sensor reads, and `First()` still costs one. The catch worth knowing: it is not thread-safe (two threads extending the cache at once would race), it holds every item it has yielded (so it is unusable on an infinite sequence — see project 30), and it must own its enumerator, which is why the constructor takes `IEnumerable<T>` but stores `GetEnumerator()`. .NET has no built-in for this; when you need it in production the usual answers are `System.Reactive`'s `Replay` or an explicit `ToList()` — but writing it once explains deferred execution better than any amount of reading about it.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

// Program.cs — the same nightly report, with every enumeration accounted for.
// Rule of thumb: a lazy query may be walked ONCE for free. If you need it
// twice, materialize it (`ToList()`) deliberately, at a named boundary, with
// a comment saying why — or fold it into one pass with Aggregate.

Console.WriteLine("=== A. materialize once at the boundary ===");

var feed = new SensorFeed(delayMs: 20);
var sw = System.Diagnostics.Stopwatch.StartNew();

// THE BOUNDARY. Everything above this line is a lazy stream that costs 20ms
// per item; everything below is an ordinary in-memory list that costs nothing
// to re-read. ToList() is where we pay, once, on purpose.
List<Reading> readings = feed.Stream().ToList();

sw.Stop();
Console.WriteLine($"sensor readings produced: {feed.Produced}   ({sw.ElapsedMilliseconds}ms)");

var stats = Statistics.Summarize(readings, alertAbove: 30m);
Console.WriteLine($"readings : {stats.Count}");
Console.WriteLine($"average  : {stats.Average:0.0}C");
Console.WriteLine($"coldest  : {stats.Min:0.0}C");
Console.WriteLine($"hottest  : {stats.Max:0.0}C");
Console.WriteLine($"alerts   : {stats.AlertCount}");
foreach (var line in Statistics.PerSensor(readings, alertAbove: 30m))
    Console.WriteLine($"  {line}");
Console.WriteLine($"sensor readings produced, after all of that: {feed.Produced}  (was 36 in the original)");

Console.WriteLine();
Console.WriteLine("=== B. or skip the list entirely: one fold, one pass ===");

// Summarize is a single Aggregate, so it can consume an expensive lazy source
// directly — no list, no second walk, no buffering of six (or six million)
// readings. This is the version to reach for when the source is huge.
var streamed = new SensorFeed(delayMs: 20);
var streamStats = Statistics.Summarize(streamed.Stream(), alertAbove: 30m);
Console.WriteLine($"same numbers straight off the stream: n={streamStats.Count} avg={streamStats.Average:0.0}C alerts={streamStats.AlertCount}");
Console.WriteLine($"sensor readings produced: {streamed.Produced}   (one pass, zero lists)");

Console.WriteLine();
Console.WriteLine("=== C. the alert threshold that no longer moves ===");

decimal alertAbove = 30m;
// Two fixes, both visible: the value is passed as an argument (so the query
// cannot read it again later), and ToList() runs the filter NOW instead of
// whenever someone happens to ask.
List<Reading> alerts = readings.Where(r => r.Celsius > alertAbove).ToList();
alertAbove = 100m;                                  // the "unrelated" line, again
Console.WriteLine($"alerts over 30C: {alerts.Count}   (the original said 0 here)");
Console.WriteLine($"and they are: {string.Join(", ", alerts.Select(a => $"{a.Sensor} {a.Celsius}C"))}");

Console.WriteLine();
Console.WriteLine("=== D. when NOT to materialize ===");

// ToList() on a lazy source means "produce EVERYTHING, now". If you only need
// the first match, that is the most expensive possible way to find it: laziness
// plus a short-circuiting operator (First/Any/Take) stops the source dead.
var peek = new SensorFeed(delayMs: 20);
Reading first = peek.Stream().First(r => r.Celsius > 30m);
Console.WriteLine($"first alert: {first.Sensor} {first.Celsius}C");
Console.WriteLine($"sensor readings produced: {peek.Produced}   (stopped as soon as it found one)");
Console.WriteLine();
Console.WriteLine("Materialize when: you need the data more than once, the source is");
Console.WriteLine("single-use (a stream/reader), or a captured variable might move.");
Console.WriteLine("Stay lazy when: the source is huge or endless, or you only need a");
Console.WriteLine("prefix (First / Any / Take) — that is project 30's whole story.");

// Two sequences you can watch: one that costs real time (the demo's sensor),
// and one that counts how often it is walked (the tests' lie detector).

/// The expensive feed from original.cs, with the Console noise removed and the
/// counter promoted to a real property. Still lazy: calling Stream() produces
/// nothing at all until somebody enumerates the result.
public sealed class SensorFeed
{
    private static readonly (string Sensor, decimal Celsius)[] Raw =
    {
        ("north", 18.5m), ("north", 31.2m), ("south", 27.0m),
        ("south", 34.8m), ("roof", 12.4m), ("roof", 22.1m),
    };

    private readonly int delayMs;

    public SensorFeed(int delayMs = 0) => this.delayMs = delayMs;

    /// How many readings this feed has actually produced, ever. The number the
    /// original could not keep down.
    public int Produced { get; private set; }

    public IEnumerable<Reading> Stream()
    {
        foreach (var (sensor, celsius) in Raw)
        {
            Produced++;
            if (delayMs > 0) Thread.Sleep(delayMs);   // a sensor / HTTP call / DB row
            yield return new Reading(sensor, celsius);
        }
    }
}

/// A sequence wrapper that records how it is used: how many enumerations were
/// started (Passes) and how many items were handed out (ItemsProduced).
/// Wrapping the real thing in a counter is the standard trick for asserting
/// "this code walks its input exactly once" — a fact no assertion about the
/// RESULT could ever catch.
public sealed class CountingSource<T> : System.Collections.Generic.IEnumerable<T>
{
    private readonly IReadOnlyList<T> items;

    public CountingSource(params T[] items) => this.items = items;

    public int Passes { get; private set; }
    public int ItemsProduced { get; private set; }

    // Because this method is an iterator, its body does not run when
    // GetEnumerator() is CALLED — it runs on the first MoveNext(). So Passes
    // counts enumerations that really started, not queries that were merely
    // built. That distinction is exactly what this project is about.
    public IEnumerator<T> GetEnumerator()
    {
        Passes++;
        foreach (var item in items)
        {
            ItemsProduced++;
            yield return item;
        }
    }

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
}

// The report's maths, as pure functions over readings. No Console, no sensor,
// no clock — just numbers in, numbers out, which is why Tests.cs can pin every
// digit of it without waiting 20ms for anything.

public readonly record struct Reading(string Sensor, decimal Celsius);

/// Everything the nightly report needs, in one value. Building it in ONE pass
/// is the whole point: five separate LINQ calls means five separate walks.
public sealed record ReadingStats(int Count, decimal Min, decimal Max, decimal Sum, int AlertCount)
{
    public static readonly ReadingStats Empty = new(0, 0m, 0m, 0m, 0);

    /// Averages are derived, not stored — Sum and Count already know it.
    /// (Guarding Count == 0 is why this is a property and not a field:
    /// LINQ's own Average() throws on an empty sequence.)
    public decimal Average => Count == 0 ? 0m : Sum / Count;

    /// Fold one more reading in. The Count == 0 checks are what make the seed
    /// honest: an empty stats object has no meaningful Min or Max yet, so the
    /// first reading defines both instead of losing to a sentinel.
    public ReadingStats Add(Reading r, decimal alertAbove) => new(
        Count: Count + 1,
        Min: Count == 0 ? r.Celsius : Math.Min(Min, r.Celsius),
        Max: Count == 0 ? r.Celsius : Math.Max(Max, r.Celsius),
        Sum: Sum + r.Celsius,
        AlertCount: AlertCount + (r.Celsius > alertAbove ? 1 : 0));
}

public static class Statistics
{
    /// ONE pass. Aggregate is LINQ's fold: start from a seed, apply a function
    /// to (accumulator, item) for each item, return the final accumulator.
    /// JS calls it `array.reduce((acc, x) => ..., seed)` — same operator, and
    /// like reduce it consumes the source exactly once, so it is safe to point
    /// at a stream, a file, a socket, or anything else you can only read once.
    public static ReadingStats Summarize(IEnumerable<Reading> readings, decimal alertAbove)
        => readings.Aggregate(ReadingStats.Empty, (stats, reading) => stats.Add(reading, alertAbove));

    /// The original's five-pass version, kept ONLY so the tests can prove the
    /// two agree on the numbers and disagree on the work. Never call this on
    /// an expensive or single-use sequence: it walks `readings` five times
    /// (and Min/Max throw on an empty one).
    public static ReadingStats SummarizeTheSlowWay(IEnumerable<Reading> readings, decimal alertAbove) => new(
        Count: readings.Count(),
        Min: readings.Min(r => r.Celsius),
        Max: readings.Max(r => r.Celsius),
        Sum: readings.Sum(r => r.Celsius),
        AlertCount: readings.Count(r => r.Celsius > alertAbove));

    /// Per-sensor report lines. GroupBy is a single pass too — it buckets as it
    /// goes — but it BUFFERS: every item is held until the source ends, so this
    /// is a "materializing" operator in all but name. Worth knowing before you
    /// aim it at a 40GB log file.
    public static IReadOnlyList<string> PerSensor(IReadOnlyList<Reading> readings, decimal alertAbove) =>
        readings
            .GroupBy(r => r.Sensor)
            .OrderBy(g => g.Key, StringComparer.Ordinal)
            .Select(g =>
            {
                var s = Summarize(g, alertAbove);     // one pass per group, over a buffer
                return $"{g.Key,-6} n={s.Count} avg={s.Average:0.0}C max={s.Max:0.0}C alerts={s.AlertCount}";
            })
            .ToList();
}

// Tests.cs — two kinds of assertion. The usual kind checks the ANSWER; the
// interesting kind checks how much WORK was done to get it, by wrapping the
// source in a counter. Performance facts you cannot assert on tend to rot.
public static class Tests
{
    // A fixed, boring dataset: n=3, sum=66, avg=22, min=10, max=36, one alert.
    private static Reading[] Sample() =>
    [
        new("a", 10m),
        new("b", 20m),
        new("c", 36m),
    ];

    public static int Run()
    {
        Console.WriteLine("the maths");
        var s = Statistics.Summarize(Sample(), alertAbove: 30m);
        Check.Equal(3, s.Count, "Count counts every reading");
        Check.Equal(10m, s.Min, "Min finds the coldest");
        Check.Equal(36m, s.Max, "Max finds the hottest");
        Check.Equal(66m, s.Sum, "Sum adds them all up");
        Check.Equal(22m, s.Average, "Average is Sum / Count");
        Check.Equal(1, s.AlertCount, "AlertCount counts readings strictly above the threshold");

        Console.WriteLine("edges the seed has to survive");
        var empty = Statistics.Summarize([], alertAbove: 30m);
        Check.Equal(0, empty.Count, "an empty sequence folds to Count 0");
        Check.Equal(0m, empty.Average, "and to Average 0 instead of a divide-by-zero");
        var one = Statistics.Summarize([new Reading("a", 7.5m)], alertAbove: 30m);
        Check.Equal(7.5m, one.Min, "a single reading defines Min");
        Check.Equal(7.5m, one.Max, "...and Max — the seed never leaks a sentinel");
        var atThreshold = Statistics.Summarize([new Reading("a", 30m)], alertAbove: 30m);
        Check.Equal(0, atThreshold.AlertCount, "exactly 30C is not 'above 30C' — the boundary is pinned");

        Console.WriteLine("the fold agrees with the five-pass original");
        var slow = Statistics.SummarizeTheSlowWay(Sample(), alertAbove: 30m);
        Check.Equal(slow, s, "one Aggregate produces exactly the numbers five LINQ calls do");

        Console.WriteLine("how many times the source gets walked");
        var counted = new CountingSource<Reading>(Sample());
        Statistics.SummarizeTheSlowWay(counted, alertAbove: 30m);
        Check.Equal(5, counted.Passes, "the original's five stats = five full enumerations");
        Check.Equal(15, counted.ItemsProduced, "3 readings, produced 15 times");

        var once = new CountingSource<Reading>(Sample());
        Statistics.Summarize(once, alertAbove: 30m);
        Check.Equal(1, once.Passes, "Aggregate walks the source exactly once");
        Check.Equal(3, once.ItemsProduced, "3 readings, produced 3 times — the 5x tax is gone");

        var boundary = new CountingSource<Reading>(Sample());
        var materialized = boundary.ToList();                 // pay once, on purpose
        Statistics.SummarizeTheSlowWay(materialized, alertAbove: 30m);
        Statistics.SummarizeTheSlowWay(materialized, alertAbove: 30m);
        Check.Equal(1, boundary.Passes, "after ToList(), even ten passes never touch the source again");

        Console.WriteLine("deferred execution, stated as facts");
        var lazy = new CountingSource<Reading>(Sample());
        var query = lazy.Where(r => r.Celsius > 5m).Select(r => r.Celsius);
        Check.Equal(0, lazy.Passes, "building a query runs NOTHING — Where/Select are recipes");
        _ = query.Count();
        Check.Equal(1, lazy.Passes, "asking for a result is what runs it");
        _ = query.Count();
        Check.Equal(2, lazy.Passes, "asking again runs it AGAIN — queries are not results");

        var stopper = new CountingSource<Reading>(Sample());
        var firstMatch = stopper.First(r => r.Celsius >= 20m);
        Check.Equal(20m, firstMatch.Celsius, "First finds the right reading");
        Check.Equal(2, stopper.ItemsProduced, "...having produced only 2 of the 3 — short-circuiting is why laziness pays");

        Console.WriteLine("the captured variable that moved");
        decimal threshold = 30m;
        var deferred = Sample().Where(r => r.Celsius > threshold);   // a recipe...
        var pinned = Sample().Where(r => r.Celsius > threshold).ToList();  // ...and a result
        threshold = 100m;
        Check.Equal(0, deferred.Count(), "the deferred query re-read the variable and saw 100 — the original's bug");
        Check.Equal(1, pinned.Count, "the materialized one kept the answer it computed at 30");

        Console.WriteLine("per-sensor grouping");
        var lines = Statistics.PerSensor(
            [new("north", 10m), new("north", 40m), new("roof", 5m)], alertAbove: 30m);
        Check.Equal(2, lines.Count, "one line per sensor");
        Check.Equal("north  n=2 avg=25.0C max=40.0C alerts=1", lines[0], "groups are summarized with the same single-pass fold");
        Check.Equal("roof   n=1 avg=5.0C max=5.0C alerts=0", lines[1], "and ordered by sensor name");

        return Check.Summary();
    }
}
